before.content:
this.profiles = profiles;
this.resources = resources;
this.devices = devices.orElseGet(() -> new HostDeviceRegistry("local-host", tokens));
this.hcp = profiles.map(service -> new HcpSessionGateway(prompts, service, this.devices, "local-host"))
        .orElseGet(() -> new HcpSessionGateway(prompts, null, this.devices, "local-host"));
this.defaultModel = defaultModel;
this.tokens = tokens;
this.workspaceId = requiredScopeText(workspaceId, "workspaceId");

after.content:
this.profiles = profiles;
this.resources = resources;
this.devices = devices.orElseGet(() -> new HostDeviceRegistry("local-host", tokens));
this.hcp = profiles.map(service -> new HcpSessionGateway(
                prompts, service, this.devices, permissions, "local-host"))
        .orElseGet(() -> new HcpSessionGateway(
                prompts, null, this.devices, permissions, "local-host"));
this.defaultModel = defaultModel;
this.tokens = tokens;
this.workspaceId = requiredScopeText(workspaceId, "workspaceId");
